static bool __york_file(const char* path, const char* content, const char* mode) {
    FILE* f = fopen(path, mode);
    if (!f) return false;
    fputs(content, f);
    fclose(f);
    return true;
}
static bool __york_write_file(const char* path, const char* content) {
    return __york_file(path, content, "wb");
}
static bool __york_append_file(const char* path, const char* content) {
    return __york_file(path, content, "ab");
}

static const char* __york_strcat(const char* a, const char* b) {
    size_t la = strlen(a), lb = strlen(b);
    char* out = (char*)malloc(la + lb + 1);
    memcpy(out, a, la);
    memcpy(out + la, b, lb);
    out[la + lb] = 0;
    return out;
}

